        {
            "id": "investor_components",
            "operator": "Integrate",
            "inputs": ["net_cash_flow_per_investor", "total_sector_investment_per_investor"],
            "left_on": ["investor_id"],
            "right_on": ["investor_id"],
            "join_type": "inner"
        },
        {
            "id": "investor_components_with_shift",
            "operator": "Integrate",
            "inputs": ["investor_components", "total_allocation_shift_per_investor"],
            "left_on": ["investor_id"],
            "right_on": ["investor_id"],
            "join_type": "inner"
        },
        {
            "id": "investor_components_with_risk",
            "operator": "Integrate",
